_IMG_CACHE = {}


def embedded_pil(name):
    """내장 이미지를 PIL(RGBA)로 돌려준다. name = logo_square | logo_kyobo | logo_korean | penguin | brand_logo"""
    from PIL import Image as PILImage
    if name in _IMG_CACHE:
        return _IMG_CACHE[name]
    if name == "brand_logo":                         # KYOBO 새싹 로고 + 교보생명 글자를 위아래로 합친다
        ky, ko = embedded_pil("logo_kyobo"), embedded_pil("logo_korean")
        w = ky.size[0]
        kw = int(w * 0.62)
        kh = int(kw * ko.size[1] / ko.size[0])
        gap = int(w * 0.06)
        im = PILImage.new("RGBA", (w, ky.size[1] + gap + kh), (255, 255, 255, 0))
        im.alpha_composite(ky, (0, 0))
        im.alpha_composite(ko.resize((kw, kh), PILImage.LANCZOS), ((w - kw) // 2, ky.size[1] + gap))
    else:
        im = PILImage.open(io.BytesIO(base64.b64decode("".join(IMG_B64[name].split())))).convert("RGBA")
    _IMG_CACHE[name] = im
    return im


def embedded_png(name):
    buf = io.BytesIO()
    embedded_pil(name).save(buf, "PNG")
    return buf.getvalue()


def get_image(name, width_mm=None, height_mm=None, h_align="LEFT"):
    """내장 이미지를 가로(또는 세로) 길이(mm)에 맞춰 PDF 용 그림으로 만든다. 비율은 유지한다."""
    iw, ih = embedded_pil(name).size
    if width_mm is not None:
        w = width_mm * mm
        h = w * ih / iw
    else:
        h = height_mm * mm
        w = h * iw / ih
    img = Image(io.BytesIO(embedded_png(name)), width=w, height=h)
    img.hAlign = h_align
    return img



def embedded_image(b64, width_mm, h_align):
    """base64 이미지를 가로 폭(mm)에 맞춰 불러온다. 세로는 원본 비율로 계산하므로 모양이 변하지 않는다."""
    raw = base64.b64decode("".join(b64.split()))
    iw, ih = ImageReader(io.BytesIO(raw)).getSize()
    w = width_mm * mm
    img = Image(io.BytesIO(raw), width=w, height=w * ih / iw)
    img.hAlign = h_align
    return img


def brand_header(width=None):
    """첫 쪽 맨 위에 넣는 로고(왼쪽) + 펭귄 이미지(오른쪽). 실패해도 요약 PDF 만들기는 계속한다."""
    try:
        logo = get_image("brand_logo", width_mm=LOGO_WIDTH_MM, h_align="LEFT")
        peng = get_image("penguin", width_mm=PENGUIN_WIDTH_MM, h_align="RIGHT")
    except Exception as ex:
        print(f"[주의] 내장 이미지를 불러오지 못했습니다: {ex}")
        return []
    t = Table([[logo, peng]], colWidths=[(width or CW) - PENGUIN_WIDTH_MM * mm, PENGUIN_WIDTH_MM * mm])
    t.setStyle(TableStyle([("VALIGN", (0, 0), (-1, -1), "TOP"),
                           ("LEFTPADDING", (0, 0), (-1, -1), 0), ("RIGHTPADDING", (0, 0), (-1, -1), 0),
                           ("TOPPADDING", (0, 0), (-1, -1), 0), ("BOTTOMPADDING", (0, 0), (-1, -1), 0)]))
    return [t, Spacer(1, 4 * mm)]


